import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const i="/images/relay/api-keys-empty.png",d="/images/relay/create-api-key.png",n="/images/relay/api-key-created.png",y=JSON.parse('{"title":"创建 API Key","description":"","frontmatter":{},"headers":[],"relativePath":"relay/api-keys.md","filePath":"relay/api-keys.md","lastUpdated":1786861842000}'),l={name:"relay/api-keys.md"};function s(c,e,p,g,h,_){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="创建-api-key" tabindex="-1">创建 API Key <a class="header-anchor" href="#创建-api-key" aria-label="Permalink to &quot;创建 API Key&quot;">​</a></h1><p>API Key 是 Codex 访问中转服务的凭据。一个密钥可以绑定一个分组，并单独设置额度、速率、有效期和 IP 限制。</p><h2 id="_1-打开-api-密钥" tabindex="-1">1. 打开 API 密钥 <a class="header-anchor" href="#_1-打开-api-密钥" aria-label="Permalink to &quot;1. 打开 API 密钥&quot;">​</a></h2><p>登录<a href="https://liangkezaoshu.top/" target="_blank" rel="noreferrer">两颗枣树控制台</a>，在左侧进入 <strong>API 密钥</strong>。第一次进入时会看到空列表，点击右上角或空状态中的 <strong>创建密钥</strong>。</p><figure class="doc-figure"><a href="/images/relay/api-keys-empty.png" target="_blank" rel="noreferrer"><img src="'+i+'" alt="API 密钥页面的空列表和创建密钥按钮，敏感信息已隐藏" loading="lazy"></a><figcaption>API 密钥页面：从右上角或空状态创建第一把密钥。界面截图已脱敏。</figcaption></figure><h2 id="_2-填写创建表单" tabindex="-1">2. 填写创建表单 <a class="header-anchor" href="#_2-填写创建表单" aria-label="Permalink to &quot;2. 填写创建表单&quot;">​</a></h2><p>按实际用途填写名称和分组，其余限制按需开启。不要为了“更安全”随意填写不确定的 IP 或过短的有效期，否则 Codex 可能在配置完成后立即被拒绝。</p><figure class="doc-figure"><a href="/images/relay/create-api-key.png" target="_blank" rel="noreferrer"><img src="'+d+'" alt="创建 API 密钥弹窗，包含名称、分组和限制选项，敏感信息已隐藏" loading="lazy"></a><figcaption>创建密钥弹窗：先选择分组，再决定是否启用各项限制。</figcaption></figure><table tabindex="0"><thead><tr><th>字段</th><th>怎么填</th></tr></thead><tbody><tr><td>名称</td><td>用设备或用途命名，例如 <code>codex-mac</code>、<code>codex-work</code>。</td></tr><tr><td>分组</td><td>选择管理员为 Codex 开放的分组；可用模型和倍率以列表为准。</td></tr><tr><td>自定义密钥</td><td>一般保持关闭；只有在需要固定凭据格式时才开启。</td></tr><tr><td>IP 限制</td><td>只有出口 IP 固定时才启用，移动网络或代理环境不要猜测填写。</td></tr><tr><td>额度限制</td><td>单位为 USD；页面提示的 <code>0</code> 表示不限制。</td></tr><tr><td>速率限制</td><td>需要限制并发或请求频率时再开启。</td></tr><tr><td>密钥有效期</td><td>按项目周期设置；临时测试可设置较短时间。</td></tr></tbody></table><p>填写完成后点击 <strong>创建</strong>。创建成功后不要把完整密钥放进仓库、截图或聊天记录。</p><h2 id="_3-从列表进入-codex-配置" tabindex="-1">3. 从列表进入 Codex 配置 <a class="header-anchor" href="#_3-从列表进入-codex-配置" aria-label="Permalink to &quot;3. 从列表进入 Codex 配置&quot;">​</a></h2><p>回到列表，确认密钥处于活跃状态、分组正确，再点击该行的 <strong>使用密钥</strong>。这个入口会根据当前服务版本和分组生成 Codex 配置，下一步直接按<a href="/relay/codex">配置 Codex</a>操作。</p><figure class="doc-figure"><a href="/images/relay/api-key-created.png" target="_blank" rel="noreferrer"><img src="'+n+'" alt="创建成功后的 API 密钥列表，展示状态和使用密钥等操作，敏感信息已隐藏" loading="lazy"></a><figcaption>创建成功后的列表：密钥值只显示掩码，使用密钥是配置 Codex 的入口。</figcaption></figure><h2 id="_4-后续管理" tabindex="-1">4. 后续管理 <a class="header-anchor" href="#_4-后续管理" aria-label="Permalink to &quot;4. 后续管理&quot;">​</a></h2><ul><li><strong>禁用</strong>：临时停止调用，恢复后再启用。</li><li><strong>编辑</strong>：调整分组或限制；修改后重新检查 Codex 配置。</li><li><strong>删除</strong>：确认没有设备继续使用后再删除，删除后不能恢复。</li><li><strong>轮换</strong>：怀疑泄露时，先创建并验证新密钥，再禁用、删除旧密钥。</li></ul><p>反馈问题时只提供密钥末四位、分组和状态码，不要发送完整密钥。</p>',16)])])}const m=t(l,[["render",s]]);export{y as __pageData,m as default};
